func newUnitTool() unsafe.Pointer { return unsafe.Pointer(new(aianalytics.UnitTool)) }

func newNUnitTool(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]aianalytics.UnitTool, n)))
}

func ptrUnitTool(p unsafe.Pointer, c int32) any {
	r := (*aianalytics.UnitTool)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return &r.UnitID
	case 3:
		return &r.ToolName
	case 4:
		return (*string)(unsafe.Pointer(&r.Cause))
	case 5:
		return &r.FinishedAt
	case 6:
		return &r.ModelKey
	case 7:
		return &r.ProviderID
	case 8:
		return &r.AgentDefinitionID
	case 9:
		return (*string)(unsafe.Pointer(&r.Task))
	case 10:
		return (*int64)(unsafe.Pointer(&r.Calls))
	}
	return nil
}

func valueUnitTool(p unsafe.Pointer, c int32) any {
	r := (*aianalytics.UnitTool)(p)
	switch c {
	case 0:
		return string(r.OrganizationID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return r.UnitID
	case 3:
		return r.ToolName
	case 4:
		return string(r.Cause)
	case 5:
		return r.FinishedAt
	case 6:
		return r.ModelKey
	case 7:
		return r.ProviderID
	case 8:
		return r.AgentDefinitionID
	case 9:
		return string(r.Task)
	case 10:
		return int64(r.Calls)
	}
	return nil
}

