func valueWorkUnit(p unsafe.Pointer, c int32) any {
	r := (*aianalytics.WorkUnit)(p)
	switch c {
	case 0:
		return r.ID
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.Source)
	case 4:
		if r.AgentDefinitionID == "" {
			return nil
		}
		return string(r.AgentDefinitionID)
	case 5:
		if r.ProviderID == "" {
			return nil
		}
		return string(r.ProviderID)
	case 6:
		return r.Model
	case 7:
		return r.ModelKey
	case 8:
		return string(r.Task)
	case 9:
		return string(r.Outcome)
	case 10:
		if r.DecisionRunID == "" {
			return nil
		}
		return string(r.DecisionRunID)
	case 11:
		return r.StartedAtMs
	case 12:
		return r.FinishedAt
	case 13:
		return r.DurationMs
	case 14:
		if r.FirstTokenMs == nil {
			return nil
		}
		return *r.FirstTokenMs
	case 15:
		return int64(r.ModelCalls)
	case 16:
		return int64(r.FailedCalls)
	case 17:
		return int64(r.Failovers)
	case 18:
		return r.InputTokens
	case 19:
		return r.OutputTokens
	case 20:
		if r.CostUSD == nil {
			return nil
		}
		return *r.CostUSD
	case 21:
		return r.CacheReadTokens
	case 22:
		return r.CacheWriteTokens
	case 23:
		return int64(r.AdvisorCalls)
	case 24:
		return r.AdvisorPromptTokens
	case 25:
		return r.AdvisorOutputTokens
	case 26:
		if r.AdvisorCostUSD == nil {
			return nil
		}
		return *r.AdvisorCostUSD
	case 27:
		return int64(r.ToolCalls)
	case 28:
		return int64(r.ToolFailuresModel)
	case 29:
		return int64(r.ToolFailuresTool)
	case 30:
		return r.RefreshStamp
	}
	return nil
}

// intIs64 fails the build where int is not 64 bits: int fields are read through *int64.
const intIs64 = unsafe.Sizeof(int(0)) - 8

var enumAitaskTask = [...]schema.EnumValue{
	{Value: `DocumentClassification`, Label: `Document Classification`},
	{Value: `DocumentExtraction`, Label: `Document Extraction`},
	{Value: `BillingDiagnosis`, Label: `Billing Diagnosis`},
	{Value: `FormulaAssistant`, Label: `Formula Assistant`},
	{Value: `ScopeClassification`, Label: `Scope Classification`, Doc: `TaskScopeClassification decides whether a request belongs to this system at all. It runs on every chat turn and needs only a yes/no with a category, so it is the cheapest thing to route to a small local model.`},
	{Value: `AssistantChat`, Label: `Assistant Chat`, Doc: `TaskAssistantChat answers a person's question and drives the tool loop.`},
	{Value: `OperationalInsights`, Label: `Operational Insights`, Doc: `TaskOperationalInsights writes the prose on a home-screen insight. It never produces a number, a severity or a link — those are computed before it runs and checked after it — so it is safe to route to whatever is cheapest.`},
	{Value: `DailyBriefing`, Label: `Daily Briefing`, Doc: `TaskDailyBriefing writes the morning page from figures already gathered. Like the insight narration it produces only wording, and every number it writes is checked against those figures afterwards, so it is safe to route wherever is cheapest.`},
	{Value: `QueryCompose`, Label: `Query Compose`, Doc: `TaskQueryCompose turns a sentence into a table's filters. It names fields and values from a catalogue it is shown and writes no SQL; everything it names is compiled against that catalogue afterwards, so a cheap model that guesses wrong produces an unresolved line rather than a wrong answer.`},
	{Value: `ChapterTitling`, Label: `Chapter Titling`, Doc: `TaskChapterTitling decides whether a Desk question starts a new chapter and names it in a few words. It runs once per question on a short prompt and its answer is cleaned and checked against the conversation afterwards, so the cheapest fast model is the right one.`},
	{Value: `InboundClassification`, Label: `Inbound Classification`, Doc: `TaskInboundClassification decides what an email that arrived actually is. Like the other classifiers it answers with a label from a fixed set, and the label is re-checked against that set afterwards — a model that invents a category produces a message for a person, not a new kind of work.`},
	{Value: `AccountingMapping`, Label: `Accounting Mapping`},
	{Value: `RemittanceExtraction`, Label: `Remittance Extraction`, Doc: `TaskRemittanceExtraction reads the lines of a factor's PDF remittance. It is kept apart from DocumentExtraction because the fine-tuned extraction model, its shadow runs and its training data all key on that task, and a remittance is not the kind of document they were built for. What it reads is matched to schedule items and a person applies it, so it never books anything on its own.`},
	{Value: `PaperworkReading`, Label: `Paperwork Reading`, Doc: `TaskPaperworkReading reads a shipment's billing paperwork (a proof of delivery, a bill of lading, a receipt) for the facts billing checks. It runs through the Nova harness, a single structured call that reads the file itself, so a fast model answers in seconds without waiting for the document to be converted.`},
	{Value: `PaletteAnswer`, Label: `Palette Answer`, Doc: `TaskPaletteAnswer answers a quick question typed into the command palette: a short streamed answer from a few read-only lookups, run through the Nova harness rather than as a Desk turn.`},
	{Value: `EvaluationJudge`, Label: `Evaluation Judge`},
	{Value: `Embedding`, Label: `Embedding`},
	{Value: `General`, Label: `General`},
}

